'use strict';

const express = require('express');
const { generateId } = require('../utils/id');
const { sendError } = require('../utils/errors');

const PLAYERS_COLLECTION = 'players';
const QUEUE_COLLECTION = 'matchmaking_queue';
const MATCHES_COLLECTION = 'matchmaking_matches';

/**
 * Creates the Matchmaking Express router.
 * 
 * @param {object} options
 * @param {object} options.storage - Conforming storage adapter
 * @param {number} [options.ratingRange=100] - Max rating difference to consider a match
 * @returns {import('express').Router}
 */
function createMatchmakingRouter({ storage, ratingRange = 100 }) {
  const router = express.Router();
  router.use(express.json());

  /**
   * POST /join
   * Join matchmaking queue.
   * Body: { playerId: string, rating: number }
   */
  router.post('/join', async (req, res, next) => {
    try {
      const { playerId, rating } = req.body || {};

      if (!playerId || typeof playerId !== 'string' || playerId.trim().length === 0) {
        return sendError(res, 400, 'playerId is required and must be a string');
      }

      if (rating === undefined || typeof rating !== 'number' || !Number.isFinite(rating)) {
        return sendError(res, 400, 'rating is required and must be a finite number');
      }

      const cleanPlayerId = playerId.trim();

      // Check player exists
      const player = await storage.get(PLAYERS_COLLECTION, cleanPlayerId);
      if (!player) {
        return sendError(res, 404, 'Player not found');
      }

      // Check if already matched
      const existingMatch = await storage.get(MATCHES_COLLECTION, cleanPlayerId);
      if (existingMatch) {
        return res.status(200).json(existingMatch);
      }

      // Check current waiting queue for eligible opponent
      const queueList = await storage.list(QUEUE_COLLECTION);
      const eligibleOpponent = queueList.find(
        entry => entry.playerId !== cleanPlayerId && Math.abs(entry.rating - rating) <= ratingRange
      );

      if (eligibleOpponent) {
        // Remove opponent from queue
        await storage.delete(QUEUE_COLLECTION, eligibleOpponent.playerId);
        // Remove current player if they were queued
        await storage.delete(QUEUE_COLLECTION, cleanPlayerId);

        const matchId = generateId('m_');
        const now = new Date().toISOString();

        const matchRecord1 = {
          status: 'matched',
          matchId,
          playerId: cleanPlayerId,
          opponentId: eligibleOpponent.playerId,
          matchedAt: now
        };

        const matchRecord2 = {
          status: 'matched',
          matchId,
          playerId: eligibleOpponent.playerId,
          opponentId: cleanPlayerId,
          matchedAt: now
        };

        await storage.set(MATCHES_COLLECTION, cleanPlayerId, matchRecord1);
        await storage.set(MATCHES_COLLECTION, eligibleOpponent.playerId, matchRecord2);

        return res.status(200).json(matchRecord1);
      }

      // No opponent found, add/update in waiting queue
      const queueEntry = {
        status: 'waiting',
        playerId: cleanPlayerId,
        rating,
        queuedAt: new Date().toISOString()
      };

      await storage.set(QUEUE_COLLECTION, cleanPlayerId, queueEntry);

      return res.status(200).json(queueEntry);
    } catch (err) {
      next(err);
    }
  });

  /**
   * GET /status/:playerId
   * Check status of player in matchmaking.
   */
  router.get('/status/:playerId', async (req, res, next) => {
    try {
      const { playerId } = req.params;

      if (!playerId || typeof playerId !== 'string' || playerId.trim().length === 0) {
        return sendError(res, 400, 'Invalid playerId');
      }

      const cleanPlayerId = playerId.trim();

      // Check if matched
      const match = await storage.get(MATCHES_COLLECTION, cleanPlayerId);
      if (match) {
        return res.status(200).json(match);
      }

      // Check if waiting in queue
      const queued = await storage.get(QUEUE_COLLECTION, cleanPlayerId);
      if (queued) {
        return res.status(200).json(queued);
      }

      return sendError(res, 404, 'Player not in matchmaking queue');
    } catch (err) {
      next(err);
    }
  });

  /**
   * POST /leave
   * Leave matchmaking queue.
   * Body: { playerId: string }
   */
  router.post('/leave', async (req, res, next) => {
    try {
      const { playerId } = req.body || {};

      if (!playerId || typeof playerId !== 'string' || playerId.trim().length === 0) {
        return sendError(res, 400, 'playerId is required and must be a string');
      }

      const cleanPlayerId = playerId.trim();
      const queued = await storage.get(QUEUE_COLLECTION, cleanPlayerId);

      if (!queued) {
        return sendError(res, 404, 'Player not found in queue');
      }

      await storage.delete(QUEUE_COLLECTION, cleanPlayerId);

      return res.status(200).json({ message: 'Left matchmaking queue' });
    } catch (err) {
      next(err);
    }
  });

  return router;
}

module.exports = {
  createMatchmakingRouter
};
